SELECT CASE WHEN c.segment IN ('Consumer', 'Corporate') THEN 'priority' ELSE 'other' END AS segment_group, MAX(a.balance) - MIN(a.balance) AS balance_range, COUNT(DISTINCT a.balance) AS unique_statuss FROM accounts a INNER JOIN customers c ON a.customer_id = c.id WHERE NOT c.is_active GROUP BY CASE WHEN c.segment IN ('Consumer', 'Corporate') THEN 'priority' ELSE 'other' END HAVING MAX(a.balance) - MIN(a.balance) >= 55;
